"""PDF B.8.7 time-keyed state schedule S-001..S-079 (p.100-102) and B.12.3 epilogue states S-080..S-088 (p.118).
Every row keeps its printed cells; the parsed window is added only where a clock time or date is printed.
Window specs use structures_common.T strings: 'MM-DD HH:MM' clock, 'MM-DD' day start, 'MM-DD/end' 23:59 of that day.
win = (earliest, latest, default). `default` is filled only when the PDF prints a single time for the transition.
granularity: 'clock' (a clock time bounds the window) or 'date' (day boundaries from a printed date; the position inside the day is NOT known).
Row fields: id, obj (printed), frm, to, time (printed), trig, tier (printed), src (printed), structs, win, gran, parse, pod (part of day),
approx, flag, begin, finish, sub (sub-events), scen (scenarios), note, oos (out of battle scope)."""

def R(id, obj, frm, to, time, trig, tier, src, structs, win=None, gran=None, parse='phrase', pod=None, approx=False, flag=None,
      begin=None, finish=None, sub=None, scen=None, note=None, oos=False, derived=None, phases=None):
    return dict(id=id, obj=obj, frm=frm, to=to, time=time, trig=trig, tier=tier, src=src, structs=structs, win=win, gran=gran, parse=parse,
                pod=pod, approx=approx, flag=flag, begin=begin, finish=finish, sub=sub, scen=scen, note=note, oos=oos, derived=derived, phases=phases)

def D(md):            # one printed date
    return (md, md + '/end', None)

def DD(a, b):         # printed date range
    return (a, b + '/end', None)

